package com.nigson.integration.provider;

import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.function.Function;
import com.nigson.integration.provider.PrivateHttp;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;

/** Reads only the signed Integration-owned API-128 projection before any local transaction. */
public final class CareerSheetContextClient implements CareerSheetContextPort {
 public record Context(UUID applicationId,String opportunityTitle,String name,String email,String submittedAt,String state,SortedMap<String,String> approvedAnswers){public Context{approvedAnswers=Collections.unmodifiableSortedMap(new TreeMap<>(approvedAnswers));}@Override public String toString(){return "CareerSheetContext[protected]";}}
 private static final PrivateWorkload.Route ROUTE=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-128")&&r.client().equals("nigson-integration")&&r.owner().equals("experience")).findFirst().orElseThrow();
 private final URI base;private final HttpClient http;private final Function<PrivateWorkload.Route,String> credentials;
 public CareerSheetContextClient(String env,String endpoint,Function<PrivateWorkload.Route,String> credentials){URI uri=URI.create(endpoint);if(!Set.of("local","test","dev","qa","stage","prod").contains(env)||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!Set.of("","/").contains(uri.getPath()))throw new IllegalArgumentException("SHEETS_CONTEXT_CONFIG_REQUIRED");if(Set.of("local","test").contains(env)){if(!"http".equals(uri.getScheme())||!Set.of("experience","127.0.0.1","localhost").contains(uri.getHost()))throw new IllegalArgumentException("LOCAL_PRIVATE_TARGET_REQUIRED");}else if(!"https".equals(uri.getScheme())||!uri.getHost().endsWith(".internal")||uri.getPort()!=-1)throw new IllegalArgumentException("APPROVED_PRIVATE_HTTPS_REQUIRED");base=uri;this.credentials=Objects.requireNonNull(credentials);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public Context read(UUID id,UUID correlation){if(id==null||id.equals(new UUID(0,0))||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");try{String token=credentials.apply(ROUTE);if(token==null||!token.matches("[A-Za-z0-9._~+/-]{1,16384}={0,2}"))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var request=HttpRequest.newBuilder(base.resolve(ROUTE.path().replace("{id}",id.toString()))).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+token).header("Accept","application/json").header("X-Correlation-ID",correlation.toString()).GET().build();var response=PrivateHttp.send(http,request,32768,Duration.ofSeconds(6));if(response.statusCode()!=200)throw new Problem.Failure(response.statusCode()==404?ProblemCode.NOT_FOUND:response.statusCode()==403?ProblemCode.ACCESS_DENIED:ProblemCode.PROVIDER_UNAVAILABLE);if(response.headers().allValues("Content-Type").size()!=1||!response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip().equals("application/json"))throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);var json=EventCodec.JSON.readTree(response.body());if(!json.isObject()||!json.propertyNames().equals(Set.of("applicationId","opportunityTitle","name","email","submittedAt","state","approvedAnswers"))||!id.equals(ApiValues.uuid(json.path("applicationId").asString()))||!json.path("approvedAnswers").isObject()||json.path("approvedAnswers").size()>32)throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);var answers=new TreeMap<String,String>();json.path("approvedAnswers").properties().forEach(e->{if(!e.getValue().isString())throw new Problem.Failure(ProblemCode.PROVIDER_RULE_VIOLATION);answers.put(e.getKey(),e.getValue().asString());});return new Context(id,json.path("opportunityTitle").asString(),json.path("name").asString(),json.path("email").asString(),json.path("submittedAt").asString(),json.path("state").asString(),answers);}catch(Problem.Failure safe){throw safe;}catch(RuntimeException failure){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}}
}
